"""DecisionProposal module for the ATLAS architecture (L3 - Analysis & Signal).

This module defines the DecisionProposal dataclass that represents a trading
proposal generated by the analysis layer, including the action, confidence,
position size hint, and stop hint.
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import Optional


@dataclass
class DecisionProposal:
    """A trading proposal generated by the analysis layer.

    Attributes:
        action: "BUY" or "SELL" indicating the proposed trade direction.
        confidence: Confidence score in the range [0.0, 1.0].
        size_hint: Suggested position size as a fraction of available equity
            (e.g., 0.10 means 10% of equity).
        stop_hint: Suggested stop price as a float, or None if no stop is proposed.
        rationale: Optional string explaining the reasoning behind the proposal.
    """

    action: str
    confidence: float
    size_hint: float
    stop_hint: Optional[float]
    rationale: Optional[str] = None